// Unicode classification for the Ling 3.2 pre-tokenizer (no ICU).
// Tables are generated by tools/gen_unicode_tables.py.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace gufo::ext::ling3_air::text::unicode {

struct CodepointRange {
  std::uint32_t first;
  std::uint32_t last;
  std::uint8_t code;  // kLetter, kNumber, or 0x80 for White_Space
};

extern const CodepointRange kRanges[];
extern const std::size_t kRangeCount;

/// Class of one code point: the low 7 bits are a category, bit 7 is
/// White_Space. A code point that is both is reported as space, exactly as the
/// pre-tokenizer needs it.
enum Category : std::uint8_t {
  kOther = 0,
  kLetter = 1,  // \p{L}
  kNumber = 2,  // \p{N}
};

[[nodiscard]] std::uint8_t Lookup(char32_t cp) noexcept;

[[nodiscard]] inline Category CategoryOf(std::uint8_t code) noexcept {
  return static_cast<Category>(code & 0x7F);
}
[[nodiscard]] inline bool IsSpaceCode(std::uint8_t code) noexcept {
  return (code & 0x80) != 0;
}
[[nodiscard]] inline bool IsLetter(char32_t cp) noexcept {
  return CategoryOf(Lookup(cp)) == kLetter;
}
[[nodiscard]] inline bool IsNumber(char32_t cp) noexcept {
  return CategoryOf(Lookup(cp)) == kNumber;
}
[[nodiscard]] inline bool IsSpace(char32_t cp) noexcept {
  return IsSpaceCode(Lookup(cp));
}

/// One decoded code point. A byte that is not valid UTF-8 decodes as
/// 0x110000 + byte with length 1, so it never matches a letter, number or
/// space class and round-trips unchanged.
struct Decoded {
  char32_t cp;
  std::uint8_t len;
};
[[nodiscard]] Decoded Decode(std::string_view s, std::size_t pos) noexcept;
[[nodiscard]] std::size_t Codepoints(std::string_view s) noexcept;

}  // namespace gufo::ext::ling3_air::text::unicode
